const raw = $input.first().json.text || "";

// Clean escaped Markdown
let text = raw
  .replace(/\\#/g, '#')
  .replace(/\\\*/g, '*')
  .replace(/\\-/g, '-');

// Escape HTML
text = text
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Convert headings
text = text.replace(/^### (.+)$/gm, '<h3>$1</h3>');
text = text.replace(/^## (.+)$/gm, '<h2>$1</h2>');
text = text.replace(/^# (.+)$/gm, '<h1>$1</h1>');

// Bold
text = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

// Horizontal lines
text = text.replace(/^-{3,}$/gm, '<hr>');

// Numbered lists
text = text.replace(
  /^\d+\.\s+(.+)$/gm,
  '<div class="list-item">$1</div>'
);

// Bullet points
text = text.replace(
  /^\*\s+(.+)$/gm,
  '<div class="bullet-item">• $1</div>'
);

// Paragraphs / line breaks
text = text.replace(/\n{2,}/g, '<br><br>');
text = text.replace(/\n/g, '<br>');

const html = `
<div style="
  font-family: Arial, sans-serif;
  max-width: 1100px;
  margin: 0 auto;
  color: #222;
  line-height: 1.7;
">

  <div style="
    background: #f5f7fb;
    padding: 30px;
    border-radius: 16px;
    border: 1px solid #e1e5ec;
  ">

    <div style="
      background:white;
      padding:30px;
      border-radius:12px;
      border:1px solid #e5e5e5;
    ">
      ${text}
    </div>

  </div>

</div>
`;

return [
  {
    json: {
      html: html
    }
  }
];
